// Общие шаги мониторинга Banci: подготовка, слайдеры («זו אזעקת שווא», «סיום ההתרעה», «כבה את המצלמה»), завершение.
import { expect, type Page } from '@playwright/test';

/** Свайп слайдера справа налево: touch-события (iPhone/Android), иначе мышь. mouse.dragTo слайдер Expo не двигает. */
export async function slide(page: Page, label: string) {
  const el = page.getByRole('button', { name: label }).filter({ visible: true }).last();
  await expect(el).toBeVisible();
  const box = (await el.boundingBox())!;
  const y = box.y + box.height / 2, start = box.x + box.width - 20, end = box.x + 10;
  const xs = [start, ...Array.from({ length: 12 }, (_, i) => start - ((start - end) * (i + 1)) / 12)];
  const hasTouch = await page.evaluate(() => 'ontouchstart' in window);
  // Жест ловит ползунок (react-native-web PanResponder), поэтому цель — элемент под точкой старта.
  const target = (await page.evaluateHandle(([x, yy]) => document.elementFromPoint(x, yy), [start, y])).asElement()!;
  if (hasTouch) {
    // WebKit не даёт создать Touch из страницы — Playwright собирает касания сам.
    const t = (x: number) => [{ identifier: 1, clientX: x, clientY: y, pageX: x, pageY: y }];
    await target.dispatchEvent('touchstart', { touches: t(xs[0]), targetTouches: t(xs[0]), changedTouches: t(xs[0]) });
    for (const x of xs.slice(1)) await target.dispatchEvent('touchmove', { touches: t(x), targetTouches: t(x), changedTouches: t(x) });
    await target.dispatchEvent('touchend', { touches: [], targetTouches: [], changedTouches: t(end) });
  } else {
    await target.dispatchEvent('mousedown', { clientX: xs[0], clientY: y, buttons: 1 });
    for (const x of xs.slice(1)) await target.dispatchEvent('mousemove', { clientX: x, clientY: y, buttons: 1 });
    await target.dispatchEvent('mouseup', { clientX: end, clientY: y, buttons: 0 });
  }
}

/** Подготовка: проверка безопасности → камера → дети → старт. Мок задаётся первым URL вкладки. */
export async function startMonitoring(page: Page, mock: string) {
  await page.goto(`/home?mock=${mock}`);
  await page.getByRole('button', { name: /התחלת ניטור/ }).filter({ visible: true }).first().click();
  await page.getByRole('button', { name: /עוצמת צפצוף מקסימלית/ }).filter({ visible: true }).click();
  await page.getByRole('button', { name: 'השמעה', exact: true }).filter({ visible: true }).click();
  await page.getByRole('button', { name: 'שמעתי', exact: true }).filter({ visible: true }).click();
  const next = page.getByRole('button', { name: 'המשך', exact: true }).filter({ visible: true });
  await expect(next).not.toHaveAttribute('aria-disabled', 'true');
  await next.click();
  await expect(page).toHaveURL(/\/monitor\/camera/);
  await page.getByRole('button', { name: 'המשך', exact: true }).filter({ visible: true }).click();
  await expect(page).toHaveURL(/\/monitor\/children/);
  const all = page.getByRole('button', { name: 'בחירת כולם' }).filter({ visible: true });
  if (await all.count()) await all.click();
  await page.getByRole('button', { name: 'התחלת ניטור', exact: true }).filter({ visible: true }).click();
  await expect(page).toHaveURL(/\/monitor\/live/);
}

/** Завершение: закрыть тревогу (если есть) и «כבה את המצלמה» → сводка. */
export async function endMonitoring(page: Page) {
  if (!/\/monitor\/live/.test(page.url())) await page.goto('/monitor/live');
  for (const alarm of ['זו אזעקת שווא', 'סיום ההתרעה']) {
    const s = page.getByRole('button', { name: alarm }).filter({ visible: true });
    if (await s.count()) {
      await slide(page, alarm);
      await expect(s).toHaveCount(0, { timeout: 10_000 }); // окно тревоги закрылось — только потом гасим камеру
    }
  }
  const stop = page.getByRole('button', { name: 'סיום ניטור', exact: true }).filter({ visible: true });
  if (await stop.count()) await stop.click();
  else {
    await expect(async () => {
      if (/\/monitor\/live/.test(page.url())) await slide(page, 'כבה את המצלמה');
      await expect(page).toHaveURL(/\/monitor\/summary|\/home/, { timeout: 4_000 });
    }).toPass({ timeout: 20_000 });
  }
  await expect(page).toHaveURL(/\/monitor\/summary|\/home/, { timeout: 15_000 });
}
